  ('019feb75-8af1-78a2-9b1c-c5e363c3063e', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8ad3-74a3-a82a-14d661c634a7', 'transports', 'transports', 'Authenticator transport hints (e.g. usb, nfc, ble, internal, hybrid). Used to hint browser UI during sign-in.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text","array_dimensions":1}', 6, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8af3-7099-a0e9-a3087a4e16bf', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8ad3-74a3-a82a-14d661c634a7', 'credential_device_type', 'credential_device_type', 'Either ''singleDevice'' (hardware-bound) or ''multiDevice'' (synced passkey). Enforced by CHECK constraint below.', NULL, true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 7, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8af4-7f22-9b6c-babbb315a712', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8ad3-74a3-a82a-14d661c634a7', 'backup_eligible', 'backup_eligible', 'Whether this credential is eligible for backup (syncing) per the authenticator''s flags at registration.', NULL, true, false, '{"value":false}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 8, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
