  ('019feb75-8b32-76ee-a1de-2bf40e8985e4', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b13-7cf2-936a-d96be009a625', 'mfa_enrolled_at', 'mfa_enrolled_at', 'When the first MFA method was enabled', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"timestamptz"}', 6, NULL, NULL, NULL, NULL, NULL, '{}', 'module'),
