  ('019feb75-8b4c-757a-81eb-ee08f36e19fd', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b42-77a4-83be-695a8efb04b9', 'owner_id', 'owner_id', NULL, NULL, true, false, '{"schema":"jwt_public","function":"current_user_id"}', NULL, NULL, NULL, NULL, '{"name":"uuid"}', 1, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b54-782a-954b-bb2e33d5aaf7', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b42-77a4-83be-695a8efb04b9', 'service', 'service', 'The service used, e.g. `twitter` or `github`.', NULL, true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 2, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b58-7eb9-bca1-6f33bdf7bb49', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b42-77a4-83be-695a8efb04b9', 'identifier', 'identifier', 'A unique identifier for the user within the service', NULL, true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 3, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b5a-7e51-878e-c812eb732f2e', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b42-77a4-83be-695a8efb04b9', 'details', 'details', 'Additional profile details extracted from this login method', NULL, true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"jsonb"}', 4, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b5d-719d-98b0-d2a4520fef68', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b42-77a4-83be-695a8efb04b9', 'is_verified', 'is_verified', 'Whether this connected account has been verified', NULL, true, false, '{"value":false}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 5, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b84-72f2-b4b2-8e385a82e3b9', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'id', 'id', NULL, NULL, true, false, '{"function":"uuidv7"}', NULL, NULL, NULL, NULL, '{"name":"uuid"}', 0, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b89-7a57-9ddd-c396dfb5dba0', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'slug', 'slug', 'Stable identifier (e.g. ''google'', ''github'', ''custom:acme-okta''). Used as connected_accounts.service value. Custom providers must use the custom:<slug> namespace; format ^[a-z0-9][a-z0-9_-]{0,30}[a-z0-9]$ enforced by admin procedure.', '{"has_guard":true}', true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 1, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b8e-76ea-8c63-b063182e24b7', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'kind', 'kind', 'Protocol family: ''oauth2'' (manual endpoint configuration) or ''oidc'' (discovery + JWKS-verified id_token). Future kinds (''saml'') will use a different field set.', '{"has_guard":true}', true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 2, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b90-7a5e-82f2-410cf7750380', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'display_name', 'display_name', 'Human-readable label for client UIs (e.g. ''Sign in with Google'', ''Acme Okta''). Exposed via the public-safe view.', NULL, true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 3, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b92-7ea6-b22e-a2d91c5a394a', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'enabled', 'enabled', 'Whether sign-in via this provider is currently allowed. Toggled by enable_identity_provider / disable_identity_provider admin procedures. Disabled providers remain in the public-safe view as enabled=false so client UIs can grey out the button.', '{"has_guard":true}', true, false, '{"value":true}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 4, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b95-7ad0-b1fd-0af151106cfc', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'authorization_url', 'authorization_url', 'OAuth2 authorization endpoint (where the user is redirected to grant consent). Required when kind = ''oauth2''; for kind = ''oidc'' resolved from cached discovery_doc.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 5, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b97-72da-a910-812b80bb8ee1', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'token_url', 'token_url', 'OAuth2 token endpoint (exchanges authorization code for access/id tokens). Required when kind = ''oauth2''; for kind = ''oidc'' resolved from cached discovery_doc.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 6, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b98-79f9-af2e-029e10d402c9', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'userinfo_url', 'userinfo_url', 'OAuth2 userinfo endpoint (returns the user profile given an access token). Required when kind = ''oauth2''; for kind = ''oidc'' resolved from cached discovery_doc or used as a fallback when the id_token does not contain the desired claims.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 7, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b9a-70ad-871c-07268df1bd14', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'issuer_url', 'issuer_url', 'OIDC issuer URL. Discovery fetches {issuer}/.well-known/openid-configuration unless discovery_url_override is set. Required when kind = ''oidc''. Used for id_token ''iss'' claim verification.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 8, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b9b-76ad-8a86-219d473e4f36', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'discovery_url_override', 'discovery_url_override', 'Optional non-standard discovery document URL. When NULL, discovery uses {issuer_url}/.well-known/openid-configuration. Used for IdPs that publish discovery at a non-spec path.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 9, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b9c-7e6f-a010-20c732a1d981', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'discovery_doc', 'discovery_doc', 'Cached OIDC discovery document (authorization_endpoint, token_endpoint, userinfo_endpoint, jwks_uri, issuer, etc.). Refreshed by a background job; auth-server reads endpoints from here at request time when kind = ''oidc''.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"jsonb"}', 10, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b9e-74d0-b5e5-adf957c38830', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'jwks', 'jwks', 'Cached JWKS document used to verify id_token signatures. Refreshed by a background job. NULL until first successful discovery + JWKS fetch.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"jsonb"}', 11, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8b9f-7b1e-981f-9ccc67a19b1f', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'jwks_fetched_at', 'jwks_fetched_at', 'Timestamp of the most recent successful JWKS fetch. Used by the background refresher to age out cache entries and to drive cold-start fetches when NULL.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"timestamptz"}', 12, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8ba1-7097-9a49-81eea89ca033', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'client_id', 'client_id', 'OAuth2 / OIDC client_id registered with the IdP. NULL for built-in rows until an admin sets it. Providers with NULL client_id or NULL client_secret_id are treated as not-configured by the sign-in path regardless of the enabled flag.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 13, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8ba2-7752-8095-7528372b2033', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'client_secret_id', 'client_secret_id', 'Pointer to the row in user_secrets that holds the OAuth2 client_secret (encrypted at rest). NULL only briefly between create_identity_provider and the first rotate_provider_secret. Rotation writes a new user_secrets row and atomically updates this column; the raw secret is never returned to clients.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"uuid"}', 14, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8ba3-7ea0-89e5-ac03c514d3bb', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'scopes', 'scopes', 'OAuth2 scopes requested in the authorization URL. For kind = ''oidc'' the admin procedure ensures ''openid'' is always present (silently prepended if missing).', '{"has_guard":true}', true, false, '{"cast":{"name":"text","array_dimensions":1},"value":[]}', NULL, NULL, NULL, NULL, '{"name":"text","array_dimensions":1}', 15, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8ba7-7350-8a3f-62061531f685', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'extra_authorization_params', 'extra_authorization_params', 'Extra query parameters merged into the authorization URL (e.g. {"prompt":"select_account"}). Admin procedure rejects reserved OAuth/OIDC keys: client_id, redirect_uri, state, nonce, code_challenge, code_challenge_method, response_type, scope.', '{"has_guard":true}', true, false, '{"cast":{"name":"jsonb"},"value":{}}', NULL, NULL, NULL, NULL, '{"name":"jsonb"}', 16, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8baa-72b4-b1cf-58244c1fcbaa', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'acceptable_client_ids', 'acceptable_client_ids', 'Multi-platform audience allow-list. When non-empty, id_token ''aud'' is validated against client_id OR any value here. Used when one IdP project issues tokens with platform-specific audiences (web vs iOS vs Android).', '{"has_guard":true}', true, false, '{"cast":{"name":"text","array_dimensions":1},"value":[]}', NULL, NULL, NULL, NULL, '{"name":"text","array_dimensions":1}', 17, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8bad-7207-b803-35e03248861e', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'email_optional', 'email_optional', 'When true, sign-in succeeds even if the IdP does not return a verified email. The user is provisioned without an email and can add one later. When false, missing email is a hard error.', '{"has_guard":true}', true, false, '{"value":false}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 18, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019feb75-8bb0-712a-bd71-4ffaa2898740', '019feb75-7843-7bd5-a19f-88c4cbec0ee6', '019feb75-8b7e-7a85-9b53-09c3e40fc17e', 'allow_link_by_email', 'allow_link_by_email', 'When true, an OAuth/OIDC sign-in whose IdP-verified email matches an existing user account auto-links the new identity to that account. When false, an existing-email collision raises IDENTITY_EMAIL_ALREADY_REGISTERED. Only honored when the IdP marks the email as verified.', '{"has_guard":true}', true, false, '{"value":false}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 19, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
